    /*
     * Assign a TrainingRun
     * 
     * @param	parentId	UUID
     * @param	assignment 	TrainingRun 
     * @return	RunParameter
     */
    public RunParameter assignTrainingRun( UUID parentId, TrainingRun assignment ) {
	    LOGGER.info("assigning TrainingRun as " + assignment.toString() );

	    RunParameter parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( TrainingRun.class, assignment.getTrainingRunId());

	    // ------------------------------------------
		// assign the TrainingRun to the parent entity
		// ------------------------------------------ 
	    parentEntity.setTrainingRun( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the TrainingRun
	 * 
	 * @param	parentId		UUID
	 * @return	RunParameter
	 */
	public RunParameter unAssignTrainingRun( UUID parentId ) {
		RunParameter parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning TrainingRun on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the TrainingRun on the parent entithy
		// ------------------------------------------     
	    parentEntity.setTrainingRun(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}




